	regions = append(regions, detectCredentialedURIs(s)...)

	// 3. Pattern-based detection via gitleaks (secrets — always on).
	if d := getDetector(); d != nil {
		for _, f := range d.DetectString(s) {
			if f.Secret == "" {
				continue
			}
			searchFrom := 0
			for {
				idx := strings.Index(s[searchFrom:], f.Secret)
				if idx < 0 {
